engine_diff.patch:
--- a/src/main/java/com/pulsestream/telemetry/eventlog/infrastructure/R2dbcAuditTrail.java
+++ b/src/main/java/com/pulsestream/telemetry/eventlog/infrastructure/R2dbcAuditTrail.java
@@ -10,6 +10,14 @@

 public class R2dbcAuditTrail implements AuditTrail {

+    private static final String INSERT_SQL = "INSERT INTO audit_trail "
+            + "(actor, action, outcome, occurred_at, correlation_id) "
+            + "VALUES (:actor, :action, :outcome, :occurredAt, :correlationId)";
+
+    private static final String DROPPED_COUNTER = "telemetry.pipeline.dropped";
+
+    private static final String AUDIT_STAGE = "audit";
+
     private final DatabaseClient databaseClient;

     private final MeterRegistry meterRegistry;
@@ -19,10 +27,24 @@
         this.meterRegistry = meterRegistry;
     }

+    @Override
     public Mono<Void> record(AuditEntry entry) {
-        return Mono.defer(() -> databaseClient.sql("INSERT INTO audit_trail (actor, action, outcome, occurred_at, correlation_id) VALUES (:actor, :action, :outcome, :occurredAt, :correlationId)").bind("actor", entry.actor()).bind("action", entry.action()).bind("outcome", entry.outcome()).bind("occurredAt", OffsetDateTime.ofInstant(entry.timestamp(), ZoneOffset.UTC)).bind("correlationId", entry.correlationId()).fetch().rowsUpdated().then()).onErrorResume(error -> {
-            meterRegistry.counter("telemetry.pipeline.dropped", "stage", "audit").increment();
-            return Mono.empty();
-        });
+        return Mono.defer(() -> insert(entry))
+                .onErrorResume(error -> {
+                    meterRegistry.counter(DROPPED_COUNTER, "stage", AUDIT_STAGE).increment();
+                    return Mono.empty();
+                });
+    }
+
+    private Mono<Void> insert(AuditEntry entry) {
+        return databaseClient.sql(INSERT_SQL)
+                .bind("actor", entry.actor())
+                .bind("action", entry.action())
+                .bind("outcome", entry.outcome())
+                .bind("occurredAt", OffsetDateTime.ofInstant(entry.timestamp(), ZoneOffset.UTC))
+                .bind("correlationId", entry.correlationId())
+                .fetch()
+                .rowsUpdated()
+                .then();
     }
 }
